import React, { useEffect, useState } from "react";

const AdminOrders = () => {
  const [orders, setOrders] = useState([]);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchOrders = async () => { // Mark this function as async
      try {
        const res = await fetch("http://localhost:5000/api/orders");
        const data = await res.json();
        setOrders(data);
      } catch (error) {
        console.error("Failed to fetch orders", error);
      }
    };
  useEffect(() => {
    fetchOrders();
  }, []);

  return (
    <div className="p-4">
      <h2 className="text-xl font-bold mb-4">Customer Orders</h2>
      {error && <p className="text-red-500">{error}</p>}
      {orders.length === 0 ? (
        <p>No orders found.</p>
      ) : (
        <ul className="space-y-2">
  {orders.map((order) => (
    <li key={order.id} className="p-2 border rounded">
      <p><strong>Order ID:</strong> {order.id}</p>
      <p><strong>Customer:</strong> {order.customer_name}</p>
      <p><strong>Product:</strong> {order.product_name}</p>
      <p><strong>Quantity:</strong> {order.quantity}</p>
      <p><strong>Total:</strong> ₦{order.total_price}</p>
      <p><strong>Message:</strong> {order.message}</p>
      <p><strong>Placed On:</strong> {new Date(order.created_at).toLocaleString()}</p>
    </li>
  ))}
</ul>
      )}
    </div>
  );
},
)}

export default AdminOrders;
